        value.PatchedUnk1 = reader.ReadUInt32();
        value.PatchedUnk2 = reader.ReadUInt32();
        value.Unk1 = reader.ReadUInt32();
        value.Unk2 = reader.ReadUInt32();
        value.RowSize = reader.ReadUInt32();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Columns.Add(TableColumn.ReadFrom(reader));
            }
        }
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Rows.Add(TableRow.ReadFrom(reader));
            }
        }
