    internal static CameraLensW ReadFrom(BinaryReader reader)
    {
        var value = new CameraLensW();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Floats.Add(reader.ReadSingle());
            }
        }
        value.Hash = HashNameW.ReadFrom(reader);
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        Wire.WriteCount(writer, Floats.Count);
        foreach (float item in Floats)
        {
            writer.Write(item);
        }
        Hash.WriteTo(writer);
    }

    internal static void Diff(string path, CameraLensW a, CameraLensW b, List<string> diffs)
    {
