            {
                if (BitConverter.SingleToUInt32Bits(a.Floats[i]) != BitConverter.SingleToUInt32Bits(b.Floats[i])) diffs.Add($"{path}.Floats[{i}]: {a.Floats[i]} vs {b.Floats[i]}");
            }
        }
        HashNameW.Diff($"{path}.Hash", a.Hash, b.Hash, diffs);
