{
    public FrameBaseW Base { get; set; } = new();
    public List<JointNode> Nodes { get; set; } = [];
    public List<CameraLensW> Lens { get; set; } = [];

    internal static FrameCameraW ReadFrom(BinaryReader reader)
    {
        var value = new FrameCameraW();
        value.Base = FrameBaseW.ReadFrom(reader);
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Nodes.Add(JointNode.ReadFrom(reader));
            }
        }
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Lens.Add(CameraLensW.ReadFrom(reader));
            }
        }
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        Base.WriteTo(writer);
        Wire.WriteCount(writer, Nodes.Count);
        foreach (JointNode item in Nodes)
        {
            item.WriteTo(writer);
        }
        Wire.WriteCount(writer, Lens.Count);
        foreach (CameraLensW item in Lens)
        {
            item.WriteTo(writer);
        }
    }

    internal static void Diff(string path, FrameCameraW a, FrameCameraW b, List<string> diffs)
    {
        FrameBaseW.Diff($"{path}.Base", a.Base, b.Base, diffs);
        if (a.Nodes.Count != b.Nodes.Count)
        {
            diffs.Add($"{path}.Nodes: count {a.Nodes.Count} vs {b.Nodes.Count}");
        }
        else
        {
            for (int i = 0; i < a.Nodes.Count; i++)
            {
                JointNode.Diff($"{path}.Nodes[{i}]", a.Nodes[i], b.Nodes[i], diffs);
            }
        }
        if (a.Lens.Count != b.Lens.Count)
        {
            diffs.Add($"{path}.Lens: count {a.Lens.Count} vs {b.Lens.Count}");
        }
        else
        {
            for (int i = 0; i < a.Lens.Count; i++)
            {
                CameraLensW.Diff($"{path}.Lens[{i}]", a.Lens[i], b.Lens[i], diffs);
            }
        }
    }
}

