internal sealed class FrameSectorW
{
    public FrameBaseW Base { get; set; } = new();
    public List<JointNode> Nodes { get; set; } = [];
    public int Unk08 { get; set; }
    public List<float> Planes { get; set; } = [];
    public BBoxW Bounds { get; set; } = new();
    public Vector3 Unk13 { get; set; }
    public Vector3 Unk14 { get; set; }
    public HashNameW SectorName { get; set; } = new();

    internal static FrameSectorW ReadFrom(BinaryReader reader)
    {
        var value = new FrameSectorW();
        value.Base = FrameBaseW.ReadFrom(reader);
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Nodes.Add(JointNode.ReadFrom(reader));
            }
        }
        value.Unk08 = reader.ReadInt32();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Planes.Add(reader.ReadSingle());
            }
        }
        value.Bounds = BBoxW.ReadFrom(reader);
        value.Unk13 = Wire.ReadVector3(reader);
        value.Unk14 = Wire.ReadVector3(reader);
        value.SectorName = HashNameW.ReadFrom(reader);
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        Base.WriteTo(writer);
        Wire.WriteCount(writer, Nodes.Count);
        foreach (JointNode item in Nodes)
        {
            item.WriteTo(writer);
        }
        writer.Write(Unk08);
        Wire.WriteCount(writer, Planes.Count);
        foreach (float item in Planes)
        {
            writer.Write(item);
        }
        Bounds.WriteTo(writer);
        Wire.WriteVector3(writer, Unk13);
        Wire.WriteVector3(writer, Unk14);
        SectorName.WriteTo(writer);
    }

    internal static void Diff(string path, FrameSectorW a, FrameSectorW b, List<string> diffs)
    {
        FrameBaseW.Diff($"{path}.Base", a.Base, b.Base, diffs);
        if (a.Nodes.Count != b.Nodes.Count)
        {
            diffs.Add($"{path}.Nodes: count {a.Nodes.Count} vs {b.Nodes.Count}");
        }
        else
        {
            for (int i = 0; i < a.Nodes.Count; i++)
            {
                JointNode.Diff($"{path}.Nodes[{i}]", a.Nodes[i], b.Nodes[i], diffs);
            }
        }
        if (a.Unk08 != b.Unk08) diffs.Add($"{path}.Unk08: {a.Unk08} vs {b.Unk08}");
        if (a.Planes.Count != b.Planes.Count)
        {
            diffs.Add($"{path}.Planes: count {a.Planes.Count} vs {b.Planes.Count}");
        }
        else
        {
            for (int i = 0; i < a.Planes.Count; i++)
            {
                if (BitConverter.SingleToUInt32Bits(a.Planes[i]) != BitConverter.SingleToUInt32Bits(b.Planes[i])) diffs.Add($"{path}.Planes[{i}]: {a.Planes[i]} vs {b.Planes[i]}");
            }
        }
        BBoxW.Diff($"{path}.Bounds", a.Bounds, b.Bounds, diffs);
        Wire.DiffVector3($"{path}.Unk13", a.Unk13, b.Unk13, diffs);
        Wire.DiffVector3($"{path}.Unk14", a.Unk14, b.Unk14, diffs);
        HashNameW.Diff($"{path}.SectorName", a.SectorName, b.SectorName, diffs);
    }
}

