        value.UnkFlags = reader.ReadUInt32();
        value.PhysSplitSize = reader.ReadInt32();
        value.HitBoxSize = reader.ReadInt32();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Splits.Add(WeightedSplitW.ReadFrom(reader));
            }
        }
        {
