        writer.Write(Flags);
        Bounds.WriteTo(writer);
        writer.Write(DeformPartIndex);
        writer.Write(MeshIndex);
        writer.Write(MaterialIndex);
        OmTexture.WriteTo(writer);
        writer.Write(Unk181);
        writer.Write(Unk182);
        writer.Write(Unk183);
        writer.Write(BlendInfoIndex);
        writer.Write(SkeletonIndex);
        writer.Write(SkeletonHierarchyIndex);
        Wire.WriteCount(writer, RestTransforms.Count);
        foreach (Mat34 item in RestTransforms)
        {
            item.WriteTo(writer);
        }
        UnkTransform.WriteTo(writer);
        Wire.WriteCount(writer, Attachments.Count);
        foreach (ModelAttachmentW item in Attachments)
        {
            item.WriteTo(writer);
        }
        writer.Write(UnkFlags);
        writer.Write(PhysSplitSize);
        writer.Write(HitBoxSize);
        Wire.WriteCount(writer, Splits.Count);
        foreach (WeightedSplitW item in Splits)
        {
            item.WriteTo(writer);
        }
        Wire.WriteCount(writer, HitBoxes.Count);
        foreach (HitBoxW item in HitBoxes)
        {
            item.WriteTo(writer);
        }
    }

    internal static void Diff(string path, FrameModelObjectW a, FrameModelObjectW b, List<string> diffs)
    {
        FrameBaseW.Diff($"{path}.Base", a.Base, b.Base, diffs);
        if (a.Nodes.Count != b.Nodes.Count)
        {
            diffs.Add($"{path}.Nodes: count {a.Nodes.Count} vs {b.Nodes.Count}");
        }
        else
        {
            for (int i = 0; i < a.Nodes.Count; i++)
            {
                JointNode.Diff($"{path}.Nodes[{i}]", a.Nodes[i], b.Nodes[i], diffs);
            }
        }
        if (a.Flags != b.Flags) diffs.Add($"{path}.Flags: {a.Flags} vs {b.Flags}");
        BBoxW.Diff($"{path}.Bounds", a.Bounds, b.Bounds, diffs);
        if (a.DeformPartIndex != b.DeformPartIndex) diffs.Add($"{path}.DeformPartIndex: {a.DeformPartIndex} vs {b.DeformPartIndex}");
