        if (a.Unk181 != b.Unk181) diffs.Add($"{path}.Unk181: {a.Unk181} vs {b.Unk181}");
        if (a.Unk182 != b.Unk182) diffs.Add($"{path}.Unk182: {a.Unk182} vs {b.Unk182}");
        if (a.Unk183 != b.Unk183) diffs.Add($"{path}.Unk183: {a.Unk183} vs {b.Unk183}");
        if (a.BlendInfoIndex != b.BlendInfoIndex) diffs.Add($"{path}.BlendInfoIndex: {a.BlendInfoIndex} vs {b.BlendInfoIndex}");
        if (a.SkeletonIndex != b.SkeletonIndex) diffs.Add($"{path}.SkeletonIndex: {a.SkeletonIndex} vs {b.SkeletonIndex}");
        if (a.SkeletonHierarchyIndex != b.SkeletonHierarchyIndex) diffs.Add($"{path}.SkeletonHierarchyIndex: {a.SkeletonHierarchyIndex} vs {b.SkeletonHierarchyIndex}");
        if (a.RestTransforms.Count != b.RestTransforms.Count)
        {
            diffs.Add($"{path}.RestTransforms: count {a.RestTransforms.Count} vs {b.RestTransforms.Count}");
        }
        else
        {
            for (int i = 0; i < a.RestTransforms.Count; i++)
            {
                Mat34.Diff($"{path}.RestTransforms[{i}]", a.RestTransforms[i], b.RestTransforms[i], diffs);
            }
        }
        Mat34.Diff($"{path}.UnkTransform", a.UnkTransform, b.UnkTransform, diffs);
        if (a.Attachments.Count != b.Attachments.Count)
        {
            diffs.Add($"{path}.Attachments: count {a.Attachments.Count} vs {b.Attachments.Count}");
        }
        else
        {
            for (int i = 0; i < a.Attachments.Count; i++)
            {
                ModelAttachmentW.Diff($"{path}.Attachments[{i}]", a.Attachments[i], b.Attachments[i], diffs);
            }
        }
        if (a.UnkFlags != b.UnkFlags) diffs.Add($"{path}.UnkFlags: {a.UnkFlags} vs {b.UnkFlags}");
        if (a.PhysSplitSize != b.PhysSplitSize) diffs.Add($"{path}.PhysSplitSize: {a.PhysSplitSize} vs {b.PhysSplitSize}");
        if (a.HitBoxSize != b.HitBoxSize) diffs.Add($"{path}.HitBoxSize: {a.HitBoxSize} vs {b.HitBoxSize}");
        if (a.Splits.Count != b.Splits.Count)
        {
            diffs.Add($"{path}.Splits: count {a.Splits.Count} vs {b.Splits.Count}");
