    public HashNameW VertexBuffer { get; set; } = new();
    public int NumVerts { get; set; }
    public int NZero1 { get; set; }
    public byte[] OpcodeCapsule { get; set; } = [];
    public byte[] SplitCapsule { get; set; } = [];

    internal static FrameLodW ReadFrom(BinaryReader reader)
    {
        var value = new FrameLodW();
        value.Distance = reader.ReadSingle();
        value.IndexBuffer = HashNameW.ReadFrom(reader);
        value.VertexDecl = reader.ReadUInt32();
        value.VertexBuffer = HashNameW.ReadFrom(reader);
        value.NumVerts = reader.ReadInt32();
        value.NZero1 = reader.ReadInt32();
        value.OpcodeCapsule = Wire.ReadBytes(reader);
        value.SplitCapsule = Wire.ReadBytes(reader);
        return value;
