    {
        writer.Write(Distance);
        IndexBuffer.WriteTo(writer);
        writer.Write(VertexDecl);
        VertexBuffer.WriteTo(writer);
        writer.Write(NumVerts);
        writer.Write(NZero1);
        Wire.WriteBytes(writer, OpcodeCapsule);
        Wire.WriteBytes(writer, SplitCapsule);
    }

    internal static void Diff(string path, FrameLodW a, FrameLodW b, List<string> diffs)
    {
        if (BitConverter.SingleToUInt32Bits(a.Distance) != BitConverter.SingleToUInt32Bits(b.Distance)) diffs.Add($"{path}.Distance: {a.Distance} vs {b.Distance}");
