        if (a.NumVerts != b.NumVerts) diffs.Add($"{path}.NumVerts: {a.NumVerts} vs {b.NumVerts}");
        if (a.NZero1 != b.NZero1) diffs.Add($"{path}.NZero1: {a.NZero1} vs {b.NZero1}");
        Wire.DiffBytes($"{path}.OpcodeCapsule", a.OpcodeCapsule, b.OpcodeCapsule, diffs);
        Wire.DiffBytes($"{path}.SplitCapsule", a.SplitCapsule, b.SplitCapsule, diffs);
