internal sealed class FrameHeaderW
{
    public byte IsScene { get; set; }
    public float Unk1 { get; set; }
    public float Unk2 { get; set; }
    public HashNameW SceneName { get; set; } = new();
    public List<float> UnkFloats { get; set; } = [];
    public byte Unk3 { get; set; }

    internal static FrameHeaderW ReadFrom(BinaryReader reader)
    {
        var value = new FrameHeaderW();
        value.IsScene = reader.ReadByte();
        value.Unk1 = reader.ReadSingle();
        value.Unk2 = reader.ReadSingle();
        value.SceneName = HashNameW.ReadFrom(reader);
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.UnkFloats.Add(reader.ReadSingle());
            }
        }
        value.Unk3 = reader.ReadByte();
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        writer.Write(IsScene);
        writer.Write(Unk1);
        writer.Write(Unk2);
        SceneName.WriteTo(writer);
        Wire.WriteCount(writer, UnkFloats.Count);
        foreach (float item in UnkFloats)
        {
            writer.Write(item);
        }
        writer.Write(Unk3);
    }

    internal static void Diff(string path, FrameHeaderW a, FrameHeaderW b, List<string> diffs)
    {
        if (a.IsScene != b.IsScene) diffs.Add($"{path}.IsScene: {a.IsScene} vs {b.IsScene}");
        if (BitConverter.SingleToUInt32Bits(a.Unk1) != BitConverter.SingleToUInt32Bits(b.Unk1)) diffs.Add($"{path}.Unk1: {a.Unk1} vs {b.Unk1}");
        if (BitConverter.SingleToUInt32Bits(a.Unk2) != BitConverter.SingleToUInt32Bits(b.Unk2)) diffs.Add($"{path}.Unk2: {a.Unk2} vs {b.Unk2}");
        HashNameW.Diff($"{path}.SceneName", a.SceneName, b.SceneName, diffs);
        if (a.UnkFloats.Count != b.UnkFloats.Count)
        {
            diffs.Add($"{path}.UnkFloats: count {a.UnkFloats.Count} vs {b.UnkFloats.Count}");
        }
        else
        {
            for (int i = 0; i < a.UnkFloats.Count; i++)
            {
                if (BitConverter.SingleToUInt32Bits(a.UnkFloats[i]) != BitConverter.SingleToUInt32Bits(b.UnkFloats[i])) diffs.Add($"{path}.UnkFloats[{i}]: {a.UnkFloats[i]} vs {b.UnkFloats[i]}");
            }
        }
        if (a.Unk3 != b.Unk3) diffs.Add($"{path}.Unk3: {a.Unk3} vs {b.Unk3}");
    }
}

