internal sealed class PackedVertexW
{
    public Vector3 Position { get; set; }
    public Vector3 Normal { get; set; }
    public Vector3 Tangent { get; set; }
    public Vector3 Binormal { get; set; }
    public float Uv0X { get; set; }
    public float Uv0Y { get; set; }
    public float Uv1X { get; set; }
    public float Uv1Y { get; set; }
    public float Uv2X { get; set; }
    public float Uv2Y { get; set; }
    public float Uv3X { get; set; }
    public float Uv3Y { get; set; }
    public uint Color0Rgba { get; set; }
    public uint Color1Rgba { get; set; }
    public float Weight0 { get; set; }
    public float Weight1 { get; set; }
    public float Weight2 { get; set; }
    public float Weight3 { get; set; }
    public uint BoneIds { get; set; }
    public Vector3 BbCoeffs { get; set; }
    public int DamageGroup { get; set; }

    internal static PackedVertexW ReadFrom(BinaryReader reader)
    {
        var value = new PackedVertexW();
        value.Position = Wire.ReadVector3(reader);
        value.Normal = Wire.ReadVector3(reader);
        value.Tangent = Wire.ReadVector3(reader);
        value.Binormal = Wire.ReadVector3(reader);
        value.Uv0X = reader.ReadSingle();
        value.Uv0Y = reader.ReadSingle();
        value.Uv1X = reader.ReadSingle();
        value.Uv1Y = reader.ReadSingle();
        value.Uv2X = reader.ReadSingle();
        value.Uv2Y = reader.ReadSingle();
        value.Uv3X = reader.ReadSingle();
        value.Uv3Y = reader.ReadSingle();
        value.Color0Rgba = reader.ReadUInt32();
        value.Color1Rgba = reader.ReadUInt32();
        value.Weight0 = reader.ReadSingle();
        value.Weight1 = reader.ReadSingle();
        value.Weight2 = reader.ReadSingle();
        value.Weight3 = reader.ReadSingle();
        value.BoneIds = reader.ReadUInt32();
        value.BbCoeffs = Wire.ReadVector3(reader);
        value.DamageGroup = reader.ReadInt32();
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        Wire.WriteVector3(writer, Position);
        Wire.WriteVector3(writer, Normal);
        Wire.WriteVector3(writer, Tangent);
        Wire.WriteVector3(writer, Binormal);
        writer.Write(Uv0X);
        writer.Write(Uv0Y);
        writer.Write(Uv1X);
        writer.Write(Uv1Y);
        writer.Write(Uv2X);
        writer.Write(Uv2Y);
        writer.Write(Uv3X);
        writer.Write(Uv3Y);
        writer.Write(Color0Rgba);
        writer.Write(Color1Rgba);
        writer.Write(Weight0);
        writer.Write(Weight1);
        writer.Write(Weight2);
        writer.Write(Weight3);
        writer.Write(BoneIds);
        Wire.WriteVector3(writer, BbCoeffs);
        writer.Write(DamageGroup);
    }

    internal static void Diff(string path, PackedVertexW a, PackedVertexW b, List<string> diffs)
    {
        Wire.DiffVector3($"{path}.Position", a.Position, b.Position, diffs);
        Wire.DiffVector3($"{path}.Normal", a.Normal, b.Normal, diffs);
        Wire.DiffVector3($"{path}.Tangent", a.Tangent, b.Tangent, diffs);
        Wire.DiffVector3($"{path}.Binormal", a.Binormal, b.Binormal, diffs);
        if (BitConverter.SingleToUInt32Bits(a.Uv0X) != BitConverter.SingleToUInt32Bits(b.Uv0X)) diffs.Add($"{path}.Uv0X: {a.Uv0X} vs {b.Uv0X}");
        if (BitConverter.SingleToUInt32Bits(a.Uv0Y) != BitConverter.SingleToUInt32Bits(b.Uv0Y)) diffs.Add($"{path}.Uv0Y: {a.Uv0Y} vs {b.Uv0Y}");
        if (BitConverter.SingleToUInt32Bits(a.Uv1X) != BitConverter.SingleToUInt32Bits(b.Uv1X)) diffs.Add($"{path}.Uv1X: {a.Uv1X} vs {b.Uv1X}");
        if (BitConverter.SingleToUInt32Bits(a.Uv1Y) != BitConverter.SingleToUInt32Bits(b.Uv1Y)) diffs.Add($"{path}.Uv1Y: {a.Uv1Y} vs {b.Uv1Y}");
        if (BitConverter.SingleToUInt32Bits(a.Uv2X) != BitConverter.SingleToUInt32Bits(b.Uv2X)) diffs.Add($"{path}.Uv2X: {a.Uv2X} vs {b.Uv2X}");
        if (BitConverter.SingleToUInt32Bits(a.Uv2Y) != BitConverter.SingleToUInt32Bits(b.Uv2Y)) diffs.Add($"{path}.Uv2Y: {a.Uv2Y} vs {b.Uv2Y}");
        if (BitConverter.SingleToUInt32Bits(a.Uv3X) != BitConverter.SingleToUInt32Bits(b.Uv3X)) diffs.Add($"{path}.Uv3X: {a.Uv3X} vs {b.Uv3X}");
        if (BitConverter.SingleToUInt32Bits(a.Uv3Y) != BitConverter.SingleToUInt32Bits(b.Uv3Y)) diffs.Add($"{path}.Uv3Y: {a.Uv3Y} vs {b.Uv3Y}");
        if (a.Color0Rgba != b.Color0Rgba) diffs.Add($"{path}.Color0Rgba: {a.Color0Rgba} vs {b.Color0Rgba}");
        if (a.Color1Rgba != b.Color1Rgba) diffs.Add($"{path}.Color1Rgba: {a.Color1Rgba} vs {b.Color1Rgba}");
        if (BitConverter.SingleToUInt32Bits(a.Weight0) != BitConverter.SingleToUInt32Bits(b.Weight0)) diffs.Add($"{path}.Weight0: {a.Weight0} vs {b.Weight0}");
        if (BitConverter.SingleToUInt32Bits(a.Weight1) != BitConverter.SingleToUInt32Bits(b.Weight1)) diffs.Add($"{path}.Weight1: {a.Weight1} vs {b.Weight1}");
        if (BitConverter.SingleToUInt32Bits(a.Weight2) != BitConverter.SingleToUInt32Bits(b.Weight2)) diffs.Add($"{path}.Weight2: {a.Weight2} vs {b.Weight2}");
        if (BitConverter.SingleToUInt32Bits(a.Weight3) != BitConverter.SingleToUInt32Bits(b.Weight3)) diffs.Add($"{path}.Weight3: {a.Weight3} vs {b.Weight3}");
        if (a.BoneIds != b.BoneIds) diffs.Add($"{path}.BoneIds: {a.BoneIds} vs {b.BoneIds}");
        Wire.DiffVector3($"{path}.BbCoeffs", a.BbCoeffs, b.BbCoeffs, diffs);
        if (a.DamageGroup != b.DamageGroup) diffs.Add($"{path}.DamageGroup: {a.DamageGroup} vs {b.DamageGroup}");
    }
}

