    internal static NavPointW ReadFrom(BinaryReader reader)
    {
        var value = new NavPointW();
        value.Type = reader.ReadUInt16();
        value.NumChildren = reader.ReadUInt32();
        value.FlagA = reader.ReadByte();
        value.FlagB = reader.ReadByte();
        value.Name = Wire.ReadString(reader);
        value.Brnb = Wire.ReadString(reader);
        value.Brnw = Wire.ReadString(reader);
        value.BlobType = Wire.ReadString(reader);
        value.WorldId = reader.ReadUInt32();
        value.Position = Wire.ReadVector3(reader);
        value.Direction = Wire.ReadVector3(reader);
        value.HalfExtents = Wire.ReadVector3(reader);
        value.HandleId = reader.ReadUInt32();
        value.HandleLeft = reader.ReadUInt32();
        value.HandleRight = reader.ReadUInt32();
        value.CoverDirection2 = Wire.ReadVector3(reader);
        value.CoverWidth = reader.ReadSingle();
        value.CoverUnk9 = reader.ReadByte();
        value.CoverUnk10 = reader.ReadByte();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.CoverItems.Add(reader.ReadUInt32());
            }
        }
        value.CoverNearestVertex = reader.ReadUInt32();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.ContourPoints.Add(Wire.ReadVector3(reader));
            }
        }
        value.ActionUnk3 = reader.ReadSingle();
        value.ActionUnk4 = reader.ReadSingle();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.ConnectedPoints.Add(reader.ReadUInt32());
            }
        }
        value.SidewalkUnk7 = reader.ReadUInt32();
        value.StationUnk0 = reader.ReadUInt32();
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        writer.Write(Type);
        writer.Write(NumChildren);
        writer.Write(FlagA);
        writer.Write(FlagB);
        Wire.WriteString(writer, Name);
        Wire.WriteString(writer, Brnb);
        Wire.WriteString(writer, Brnw);
        Wire.WriteString(writer, BlobType);
        writer.Write(WorldId);
        Wire.WriteVector3(writer, Position);
        Wire.WriteVector3(writer, Direction);
        Wire.WriteVector3(writer, HalfExtents);
        writer.Write(HandleId);
        writer.Write(HandleLeft);
        writer.Write(HandleRight);
        Wire.WriteVector3(writer, CoverDirection2);
        writer.Write(CoverWidth);
        writer.Write(CoverUnk9);
        writer.Write(CoverUnk10);
        Wire.WriteCount(writer, CoverItems.Count);
        foreach (uint item in CoverItems)
