        if (!string.Equals(a.Name, b.Name, StringComparison.Ordinal)) diffs.Add($"{path}.Name: '{a.Name}' vs '{b.Name}'");
        if (!string.Equals(a.Brnb, b.Brnb, StringComparison.Ordinal)) diffs.Add($"{path}.Brnb: '{a.Brnb}' vs '{b.Brnb}'");
        if (!string.Equals(a.Brnw, b.Brnw, StringComparison.Ordinal)) diffs.Add($"{path}.Brnw: '{a.Brnw}' vs '{b.Brnw}'");
        if (!string.Equals(a.BlobType, b.BlobType, StringComparison.Ordinal)) diffs.Add($"{path}.BlobType: '{a.BlobType}' vs '{b.BlobType}'");
        if (a.WorldId != b.WorldId) diffs.Add($"{path}.WorldId: {a.WorldId} vs {b.WorldId}");
        Wire.DiffVector3($"{path}.Position", a.Position, b.Position, diffs);
        Wire.DiffVector3($"{path}.Direction", a.Direction, b.Direction, diffs);
        Wire.DiffVector3($"{path}.HalfExtents", a.HalfExtents, b.HalfExtents, diffs);
        if (a.HandleId != b.HandleId) diffs.Add($"{path}.HandleId: {a.HandleId} vs {b.HandleId}");
