        if (a.HandleRight != b.HandleRight) diffs.Add($"{path}.HandleRight: {a.HandleRight} vs {b.HandleRight}");
        Wire.DiffVector3($"{path}.CoverDirection2", a.CoverDirection2, b.CoverDirection2, diffs);
        if (BitConverter.SingleToUInt32Bits(a.CoverWidth) != BitConverter.SingleToUInt32Bits(b.CoverWidth)) diffs.Add($"{path}.CoverWidth: {a.CoverWidth} vs {b.CoverWidth}");
        if (a.CoverUnk9 != b.CoverUnk9) diffs.Add($"{path}.CoverUnk9: {a.CoverUnk9} vs {b.CoverUnk9}");
        if (a.CoverUnk10 != b.CoverUnk10) diffs.Add($"{path}.CoverUnk10: {a.CoverUnk10} vs {b.CoverUnk10}");
        if (a.CoverItems.Count != b.CoverItems.Count)
        {
            diffs.Add($"{path}.CoverItems: count {a.CoverItems.Count} vs {b.CoverItems.Count}");
        }
        else
        {
            for (int i = 0; i < a.CoverItems.Count; i++)
            {
                if (a.CoverItems[i] != b.CoverItems[i]) diffs.Add($"{path}.CoverItems[{i}]: {a.CoverItems[i]} vs {b.CoverItems[i]}");
            }
        }
        if (a.CoverNearestVertex != b.CoverNearestVertex) diffs.Add($"{path}.CoverNearestVertex: {a.CoverNearestVertex} vs {b.CoverNearestVertex}");
        if (a.ContourPoints.Count != b.ContourPoints.Count)
        {
