        if (BitConverter.SingleToUInt32Bits(a.ActionUnk3) != BitConverter.SingleToUInt32Bits(b.ActionUnk3)) diffs.Add($"{path}.ActionUnk3: {a.ActionUnk3} vs {b.ActionUnk3}");
