internal sealed class StblSec3W
{
    public uint A { get; set; }
    public ushort B { get; set; }

    internal static StblSec3W ReadFrom(BinaryReader reader)
    {
        var value = new StblSec3W();
        value.A = reader.ReadUInt32();
        value.B = reader.ReadUInt16();
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        writer.Write(A);
        writer.Write(B);
    }

    internal static void Diff(string path, StblSec3W a, StblSec3W b, List<string> diffs)
    {
        if (a.A != b.A) diffs.Add($"{path}.A: {a.A} vs {b.A}");
        if (a.B != b.B) diffs.Add($"{path}.B: {a.B} vs {b.B}");
    }
}

internal sealed class StblFsbW
{
    public string Path { get; set; } = "";
    public byte Unk0 { get; set; }
    public float Volume { get; set; }

    internal static StblFsbW ReadFrom(BinaryReader reader)
    {
        var value = new StblFsbW();
        value.Path = Wire.ReadString(reader);
        value.Unk0 = reader.ReadByte();
        value.Volume = reader.ReadSingle();
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        Wire.WriteString(writer, Path);
        writer.Write(Unk0);
        writer.Write(Volume);
    }

    internal static void Diff(string path, StblFsbW a, StblFsbW b, List<string> diffs)
    {
        if (!string.Equals(a.Path, b.Path, StringComparison.Ordinal)) diffs.Add($"{path}.Path: '{a.Path}' vs '{b.Path}'");
        if (a.Unk0 != b.Unk0) diffs.Add($"{path}.Unk0: {a.Unk0} vs {b.Unk0}");
        if (BitConverter.SingleToUInt32Bits(a.Volume) != BitConverter.SingleToUInt32Bits(b.Volume)) diffs.Add($"{path}.Volume: {a.Volume} vs {b.Volume}");
    }
}

internal sealed class StblVariantW
{
    public uint Id { get; set; }
    public ushort Entry1Index { get; set; }
    public List<StblFsbW> Fsbs { get; set; } = [];

    internal static StblVariantW ReadFrom(BinaryReader reader)
    {
        var value = new StblVariantW();
        value.Id = reader.ReadUInt32();
        value.Entry1Index = reader.ReadUInt16();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Fsbs.Add(StblFsbW.ReadFrom(reader));
            }
        }
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        writer.Write(Id);
        writer.Write(Entry1Index);
        Wire.WriteCount(writer, Fsbs.Count);
        foreach (StblFsbW item in Fsbs)
        {
            item.WriteTo(writer);
        }
    }

    internal static void Diff(string path, StblVariantW a, StblVariantW b, List<string> diffs)
    {
        if (a.Id != b.Id) diffs.Add($"{path}.Id: {a.Id} vs {b.Id}");
        if (a.Entry1Index != b.Entry1Index) diffs.Add($"{path}.Entry1Index: {a.Entry1Index} vs {b.Entry1Index}");
        if (a.Fsbs.Count != b.Fsbs.Count)
        {
            diffs.Add($"{path}.Fsbs: count {a.Fsbs.Count} vs {b.Fsbs.Count}");
        }
        else
        {
            for (int i = 0; i < a.Fsbs.Count; i++)
            {
                StblFsbW.Diff($"{path}.Fsbs[{i}]", a.Fsbs[i], b.Fsbs[i], diffs);
            }
        }
    }
}

internal sealed class StblGroupW
{
    public uint Id { get; set; }
    public float Unk0 { get; set; }
    public List<StblVariantW> Variants { get; set; } = [];

    internal static StblGroupW ReadFrom(BinaryReader reader)
    {
        var value = new StblGroupW();
        value.Id = reader.ReadUInt32();
        value.Unk0 = reader.ReadSingle();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Variants.Add(StblVariantW.ReadFrom(reader));
            }
        }
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        writer.Write(Id);
        writer.Write(Unk0);
        Wire.WriteCount(writer, Variants.Count);
        foreach (StblVariantW item in Variants)
        {
            item.WriteTo(writer);
        }
    }

    internal static void Diff(string path, StblGroupW a, StblGroupW b, List<string> diffs)
    {
        if (a.Id != b.Id) diffs.Add($"{path}.Id: {a.Id} vs {b.Id}");
        if (BitConverter.SingleToUInt32Bits(a.Unk0) != BitConverter.SingleToUInt32Bits(b.Unk0)) diffs.Add($"{path}.Unk0: {a.Unk0} vs {b.Unk0}");
        if (a.Variants.Count != b.Variants.Count)
        {
            diffs.Add($"{path}.Variants: count {a.Variants.Count} vs {b.Variants.Count}");
        }
        else
        {
            for (int i = 0; i < a.Variants.Count; i++)
            {
                StblVariantW.Diff($"{path}.Variants[{i}]", a.Variants[i], b.Variants[i], diffs);
            }
        }
    }
}

