internal sealed class StblFileW
{
    public byte Typed { get; set; }
    public List<StblCurveW> Curves { get; set; } = [];
    public List<StblTaggedW> Tagged { get; set; } = [];
    public List<StblSec3W> Sec3 { get; set; } = [];
    public List<StblGroupW> Groups { get; set; } = [];
    public uint StringBufferSize { get; set; }
    public List<StblNameW> Names { get; set; } = [];
    public byte[] Opaque { get; set; } = [];

    internal static StblFileW ReadFrom(BinaryReader reader)
    {
        var value = new StblFileW();
        value.Typed = reader.ReadByte();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Curves.Add(StblCurveW.ReadFrom(reader));
            }
        }
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Tagged.Add(StblTaggedW.ReadFrom(reader));
            }
        }
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Sec3.Add(StblSec3W.ReadFrom(reader));
            }
        }
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Groups.Add(StblGroupW.ReadFrom(reader));
            }
        }
        value.StringBufferSize = reader.ReadUInt32();
        {
            uint count = Wire.ReadCount(reader);
            for (uint i = 0; i < count; i++)
            {
                value.Names.Add(StblNameW.ReadFrom(reader));
            }
        }
        value.Opaque = Wire.ReadBytes(reader);
        return value;
    }

    internal void WriteTo(BinaryWriter writer)
    {
        writer.Write(Typed);
        Wire.WriteCount(writer, Curves.Count);
        foreach (StblCurveW item in Curves)
        {
            item.WriteTo(writer);
        }
        Wire.WriteCount(writer, Tagged.Count);
        foreach (StblTaggedW item in Tagged)
        {
            item.WriteTo(writer);
        }
        Wire.WriteCount(writer, Sec3.Count);
        foreach (StblSec3W item in Sec3)
        {
            item.WriteTo(writer);
        }
        Wire.WriteCount(writer, Groups.Count);
        foreach (StblGroupW item in Groups)
        {
            item.WriteTo(writer);
        }
        writer.Write(StringBufferSize);
        Wire.WriteCount(writer, Names.Count);
        foreach (StblNameW item in Names)
        {
            item.WriteTo(writer);
        }
        Wire.WriteBytes(writer, Opaque);
    }

    internal static void Diff(string path, StblFileW a, StblFileW b, List<string> diffs)
    {
        if (a.Typed != b.Typed) diffs.Add($"{path}.Typed: {a.Typed} vs {b.Typed}");
        if (a.Curves.Count != b.Curves.Count)
        {
            diffs.Add($"{path}.Curves: count {a.Curves.Count} vs {b.Curves.Count}");
        }
        else
        {
            for (int i = 0; i < a.Curves.Count; i++)
            {
                StblCurveW.Diff($"{path}.Curves[{i}]", a.Curves[i], b.Curves[i], diffs);
            }
        }
        if (a.Tagged.Count != b.Tagged.Count)
        {
            diffs.Add($"{path}.Tagged: count {a.Tagged.Count} vs {b.Tagged.Count}");
        }
        else
        {
            for (int i = 0; i < a.Tagged.Count; i++)
            {
                StblTaggedW.Diff($"{path}.Tagged[{i}]", a.Tagged[i], b.Tagged[i], diffs);
            }
        }
        if (a.Sec3.Count != b.Sec3.Count)
        {
            diffs.Add($"{path}.Sec3: count {a.Sec3.Count} vs {b.Sec3.Count}");
        }
        else
        {
            for (int i = 0; i < a.Sec3.Count; i++)
            {
                StblSec3W.Diff($"{path}.Sec3[{i}]", a.Sec3[i], b.Sec3[i], diffs);
            }
        }
        if (a.Groups.Count != b.Groups.Count)
        {
            diffs.Add($"{path}.Groups: count {a.Groups.Count} vs {b.Groups.Count}");
        }
        else
        {
            for (int i = 0; i < a.Groups.Count; i++)
            {
                StblGroupW.Diff($"{path}.Groups[{i}]", a.Groups[i], b.Groups[i], diffs);
            }
        }
        if (a.StringBufferSize != b.StringBufferSize) diffs.Add($"{path}.StringBufferSize: {a.StringBufferSize} vs {b.StringBufferSize}");
        if (a.Names.Count != b.Names.Count)
        {
            diffs.Add($"{path}.Names: count {a.Names.Count} vs {b.Names.Count}");
        }
        else
        {
            for (int i = 0; i < a.Names.Count; i++)
            {
                StblNameW.Diff($"{path}.Names[{i}]", a.Names[i], b.Names[i], diffs);
            }
        }
        Wire.DiffBytes($"{path}.Opaque", a.Opaque, b.Opaque, diffs);
    }
}

